<?php
declare(strict_types=1);
function validateSchedule(mixed $rows): array { if(!is_array($rows)||!array_is_list($rows)||count($rows)>28) fail(422,'جدول الدوام غير صالح'); $out=[]; foreach($rows as $r) { if(!is_array($r)||!isset($r['day'],$r['start'],$r['end'])||!is_int($r['day'])||$r['day']<0||$r['day']>6||!is_string($r['start'])||!is_string($r['end'])||!preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/D',$r['start'])||!preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/D',$r['end'])||$r['start']===$r['end']) fail(422,'حدد اليوم ووقت بداية ونهاية مختلفين'); $out[]=['day'=>$r['day'],'start'=>$r['start'],'end'=>$r['end']]; } return $out; }
function serviceStatus(array $s,?DateTimeImmutable $at=null): array { $at=($at??new DateTimeImmutable())->setTimezone(new DateTimeZone('Asia/Damascus')); $ts=$at->getTimestamp(); $override=($s['override_status']??null)&&strtotime($s['override_until']??'')>$ts; $rows=is_string($s['schedule']??null)?json_decode($s['schedule'],true):($s['schedule']??[]); $status='unknown'; $source='unverified'; if($override) { $status=$s['override_status']; $source='owner'; } elseif($rows) { $status='closed'; $source='schedule'; $day=(int)$at->format('w'); $minute=$at->format('H:i'); foreach($rows as $r) { $overnight=$r['end']<$r['start']; if((!$overnight&&$r['day']===$day&&$minute>=$r['start']&&$minute<$r['end'])||($overnight&&(($r['day']===$day&&$minute>=$r['start'])||(($r['day']+1)%7===$day&&$minute<$r['end'])))) { $status='open'; break; } } } $duty=!empty($s['supports_duty'])&&strtotime($s['duty_until']??'')>$ts; return ['status'=>$status,'status_source'=>$source,'on_duty'=>$duty,'server_time'=>$at->format(DATE_ATOM)]; }
